#!/bin/sh
# Builds `gamma`, the compiler in compiler/, from the seed in bootstrap/seed with nothing
# but a C compiler.
#
#   bootstrap/build.sh [OUT_DIR]       (default: target/bootstrap)
#
# The seed is the C that the compiler generated for its own sources (bootstrap/seed/SOURCE
# names them). Compiling it gives gamma0; gamma0 builds the compiler of the current sources
# (gamma1), and gamma1 builds itself again (gamma), so that the result is generated by
# the current compiler and not by the seed's. `CC` and `JOBS` are honored.
set -eu

here=$(cd "$(dirname "$0")" && pwd)
root=$(dirname "$here")
out=${1:-$root/target/bootstrap}
cc=${CC:-cc}
jobs=${JOBS:-8}
mkdir -p "$out"
out=$(cd "$out" && pwd)

# The flags the compiler compiles generated C with (BASE_CFLAGS in compiler/driver/native.gm).
flags="-std=gnu11 -w -Wno-free-nonheap-object -fwrapv -fno-strict-aliasing -ffp-contract=off -pthread -O1"

echo "bootstrap: compiling the seed with $cc"
# Every unit, $jobs at a time; a failure stops the build.
failed=0
running=0
pids=""
for src in "$here"/seed/*.c; do
    obj="$out/$(basename "$src" .c).o"
    # shellcheck disable=SC2086
    $cc $flags -I"$here/seed" -c "$src" -o "$obj" &
    pids="$pids $!"
    running=$((running + 1))
    if [ "$running" -ge "$jobs" ]; then
        for p in $pids; do wait "$p" || failed=1; done
        pids=""
        running=0
    fi
done
for p in $pids; do wait "$p" || failed=1; done
if [ "$failed" -ne 0 ]; then
    echo "bootstrap: compiling the seed failed" >&2
    exit 1
fi
# shellcheck disable=SC2046
$cc -pthread -o "$out/gamma0" $(for src in "$here"/seed/*.c; do printf '%s ' "$out/$(basename "$src" .c).o"; done) -lm

# Builds use the repository's standard library and runtime, and a cache of their own.
GAMMA_STD="$root/lib/std"
GAMMA_RUNTIME="$root/runtime"
GAMMA_CACHE_DIR="$out/cache"
export GAMMA_STD GAMMA_RUNTIME GAMMA_CACHE_DIR
cd "$root"
echo "bootstrap: building gamma with the seed's compiler"
"$out/gamma0" build compiler -o "$out/gamma1"
echo "bootstrap: building gamma with itself"
"$out/gamma1" build compiler -o "$out/gamma"
echo "bootstrap: $out/gamma"
